  const dialog=document.createElement('dialog');dialog.className='gs-import-dialog';dialog.id='gs-import-dialog';dialog.innerHTML='<h2>导入剧情</h2><p class="gs-note">支持「冰翼：台词」「【冰翼】台词」「旁白：描述」。没有角色标记的段落作为旁白保留。导入会替换当前片段，可以撤销。</p><textarea id="gs-import-text" rows="14" aria-label="剧情原文" placeholder="冰翼：今晚，想讲一个怎样的故事？"></textarea><div class="gs-row"><button id="gs-pick-text">选择 TXT / DOCX 文件</button><button id="gs-import-close">取消</button><button id="gs-parse" class="primary-button">整理成剧情片段</button></div>';document.body.append(dialog);
  let project=null,assets=[],audio=[],voices=[],layout=null,selected=0,undo=[],redo=[],pending=null,job=null,startingJob=false,loaded=false,busyChat=false;
