  $('edit-layer').addEventListener('pointerup',endDrag);$('edit-layer').addEventListener('pointercancel',endDrag);
  function editText(){if(playing||!row()||inlineEditor)return;const target=$('edit-layer').querySelector('.gs-text-hit');if(!target)return;const input=document.createElement('textarea');input.className='gs-inline-text';input.setAttribute('aria-label','画布对白编辑');input.maxLength=4000;input.value=row().text;Object.assign(input.style,{left:target.style.left,top:target.style.top,width:target.style.width,height:'19%',fontSize:Math.max(14,$('frame').clientWidth/1920*project.settings.fontSize)+'px'});inlineEditor=input;$('edit-layer').append(input);input.focus();let done=false;function finish(cancel=false){if(done)return;done=true;const value=input.value;inlineEditor=null;input.remove();if(!cancel&&value!==row().text)edit(()=>row().text=value);else editLayer();}input.onblur=()=>finish();input.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();finish(true);}if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();finish();}};}
  function editName(){if(playing||!row()||inlineEditor)return;const character=project.characters.find(c=>c.id===row().speakerId),target=$('edit-layer').querySelector('.gs-name-hit');if(!character||!target)return;const input=document.createElement('input');input.className='gs-inline-text gs-inline-name';input.setAttribute('aria-label','画布姓名牌编辑');input.maxLength=100;input.value=character.name;Object.assign(input.style,{left:target.style.left,top:target.style.top,width:target.style.width,height:target.style.height,fontSize:Math.max(14,$('frame').clientWidth/1920*27)+'px'});inlineEditor=input;$('edit-layer').append(input);input.focus();input.select();let done=false;function finish(cancel=false){if(done)return;done=true;const value=input.value.trim();inlineEditor=null;input.remove();if(!cancel&&value&&value!==character.name){edit(()=>character.name=value);status('角色姓名已修改，关联台词与剪映草稿同步更新；可撤销。');}else{editLayer();if(!cancel&&!value)status('角色姓名不能为空。');}}input.onblur=()=>finish();input.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();finish(true);}else if(e.key==='Enter'){e.preventDefault();finish();}};}
  $('edit-layer').addEventListener('dblclick',e=>{if(e.target.closest('.gs-name-hit'))editName();else if(e.target.closest('.gs-text-hit'))editText();});
