  function importControls(){for(const [id,kind] of [['audio-import','audio'],['import-bgm','bgm'],['import-background','background'],['import-sprite','sprite']])if($(id))$(id).disabled=pendingImports.has(kind);}
  function controls(){$('undo').disabled=!undo.length;$('redo').disabled=!redo.length;$('export').disabled=!!job||startingJob||!project?.clips.length;$('mp4').disabled=$('export').disabled;for(const name of ['up','down','duplicate','delete','prev','next','play'])$(name).disabled=!project?.clips.length;for(const [step,target] of [['step-import','import'],['step-preview','play'],['step-export','export']])$(step).disabled=$(target).disabled;importControls();}
