  let loadingStory=false;
  async function enterStory(){
    if(loadingStory)return;loadingStory=true;retry.disabled=true;
    try{
      await refreshLibraries();await projects();const state=await api('/api/gal-story/status');
      chatModels=state.models;
      $('model').innerHTML=state.models.length?state.models.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join(''):'<option value="">请先配置聊天模型</option>';$('model').value=state.activeModelId;renderChatIdentity();
      if(!loaded){
        let stored,warning='';const raw=localStorage.getItem('bingyi-gal-story-draft');
        try{stored=raw?JSON.parse(raw):null;}catch{warning='暂存格式无法读取，已打开保存的项目。';}
        let value;
        if(stored?.version===1){
          try{value=(await api('/api/gal-story/save',{project:stored})).project;}
          catch(error){if(![400,413,422].includes(error.status))throw error;warning='暂存无法载入，已备份并打开保存的项目。';}
        }
        if(warning&&raw){localStorage.setItem('bingyi-gal-story-recovery',raw);recovery.hidden=false;}
        value ||= await api('/api/gal-story/last');
        adopt(value,warning||'可导入剧情，或用示例短剧开始。'+(state.encoderReady?'':' 尚未检测到 FFmpeg。'));
        loaded=true;savedRevision=revision;for(const id of initialControls)$(id).disabled=false;controls();
      }else{renderCurrent();renderSettings();schedulePreview();}
      retry.hidden=true;
    }catch(error){status('剧情读取失败：'+error.message+'；可点击重新读取项目。');retry.hidden=false;}
    finally{loadingStory=false;retry.disabled=false;}
  }
  retry.onclick=enterStory;
  window.addEventListener('workshop-page',event=>{if(event.detail!=='gal-story'){pause();$('video').pause();return;}enterStory();});
  window.addEventListener('beforeunload',()=>{if(!project)return;remember();const body=JSON.stringify({project});if(new TextEncoder().encode(body).length<60000)fetch('/api/gal-story/save',{method:'POST',headers:{'Content-Type':'application/json'},body,keepalive:true}).catch(()=>{});});
